/* Bonus multiple-choice questions, written with IB command terms and markscheme-style explanations.
   MQ(subject, spec, commandTerm, question, [options], indexOfCorrect, explanation)
   Topics without a curated question get an "Identify" question built from their prompts' answer lists. */
const MCQ = [];
const MQ = (s, spec, term, q, o, a, why) => MCQ.push({s, spec, term, q, o, a, why});

/* ---------- Computer Science ---------- */
MQ("cs","A1.1.1","Identify","Identify the register that holds the address of the memory location currently being accessed.",["Memory address register (MAR)","Memory data register (MDR)","Accumulator (AC)","Instruction register (IR)"],0,"The MAR holds the address being read from or written to and sends it along the address bus. The MDR holds the data itself; the AC holds ALU results; the IR holds the current instruction.");
MQ("cs","A1.1.1","State","State which bus is bidirectional.",["Data bus","Address bus","Both address and data buses","Neither bus"],0,"The data bus is bidirectional: data travels to and from memory. The address bus is unidirectional, from the CPU to memory.");
MQ("cs","A1.1.1","Identify","Identify the component that decodes instructions.",["Control unit","Arithmetic logic unit","Cache","Accumulator"],0,"The control unit decodes the instruction in the IR and sends control signals. The ALU performs arithmetic and logic; it does not decode.");
MQ("cs","A1.1.5","Outline","Which sequence correctly outlines the start of the fetch stage?",["PC → MAR → address bus → memory → data bus → MDR → IR","MAR → PC → MDR → IR","IR → MDR → MAR → PC","PC → MDR → MAR → IR"],0,"The PC's address is copied to the MAR, sent on the address bus, and the instruction returns on the data bus into the MDR, then the IR. The PC is incremented.");
MQ("cs","A1.1.5","State","State what happens to the program counter during the fetch stage.",["It is incremented to point to the next instruction","It is cleared to zero","It stores the result of the instruction","It holds the decoded instruction"],0,"After the address is copied to the MAR, the PC is incremented so it points to the next instruction in sequence.");
MQ("cs","A1.1.4","Distinguish","Which statement correctly distinguishes RAM from ROM?",["RAM is volatile; ROM is non-volatile","RAM is read-only; ROM can be written","RAM stores the boot program; ROM stores running programs","RAM is slower than ROM"],0,"RAM loses its contents without power (volatile) and holds running programs and data. ROM keeps its contents and holds the boot instructions.");
MQ("cs","A1.1.8","Identify","Identify the compression technique that replaces repeated values with a value and a count.",["Run-length encoding","Transform coding","Lossy compression","Huffman coding"],0,"Run-length encoding stores a run such as AAAA as A4. It is lossless. Transform coding is lossy and works in the frequency domain.");
MQ("cs","A1.1.9","Identify","Identify the cloud service model in which the provider supplies complete applications to users.",["SaaS","PaaS","IaaS","FaaS"],0,"Software as a Service delivers ready-to-use applications (e.g. Google Docs). PaaS provides a platform to build apps; IaaS provides virtual hardware.");
MQ("cs","A2.1.4","State","State the TCP/IP layer responsible for routing packets between networks.",["Internet layer","Transport layer","Application layer","Network access layer"],0,"The internet layer (IP) addresses and routes packets. The transport layer (TCP/UDP) handles end-to-end delivery and ports.");
MQ("cs","A2.4.3","Identify","Identify the key used to decrypt a message encrypted with a recipient's public key.",["The recipient's private key","The recipient's public key","The sender's private key","A shared symmetric key"],0,"In asymmetric encryption, data encrypted with a public key can only be decrypted with the matching private key.");
MQ("cs","A3.2.4","Identify","Identify the normal form that removes transitive dependencies.",["Third normal form (3NF)","First normal form (1NF)","Second normal form (2NF)","Boyce–Codd normal form only"],0,"3NF requires that non-key attributes depend only on the key, removing transitive dependencies. 2NF removes partial dependencies; 1NF requires atomic values.");
MQ("cs","B2.4.1","State","State the Big O time complexity of binary search.",["O(log n)","O(n)","O(n²)","O(1)"],0,"Binary search halves the search space at each step, so it takes logarithmic time: O(log n).");
MQ("cs","B2.2.3","Identify","Identify the data structure that works on a last-in, first-out basis.",["Stack","Queue","Array","Linked list"],0,"A stack is LIFO: the last item pushed is the first popped. A queue is FIFO.");
MQ("cs","B3.1.4","Define","Which option defines encapsulation?",["Bundling data with the methods that act on it and restricting direct access to the data","Creating a new class from an existing class","Using one interface for different types","Hiding complex detail behind a simple model"],0,"Encapsulation combines attributes and methods in a class and protects the data with access modifiers. The other options describe inheritance, polymorphism and abstraction.");

/* ---------- Biology ---------- */
MQ("bio","B2.1","Identify","Identify the process that moves substances against a concentration gradient.",["Active transport","Simple diffusion","Facilitated diffusion","Osmosis"],0,"Active transport uses ATP and protein pumps to move substances from low to high concentration. Diffusion and osmosis are passive and go down a gradient.");
MQ("bio","D1.1","State","State why DNA replication is described as semi-conservative.",["Each new molecule has one original strand and one new strand","Both strands of the original molecule are kept together","Only half the genes are copied","Each new molecule is made of two new strands"],0,"Each daughter DNA molecule contains one parental strand, which acted as a template, and one newly built strand.");
MQ("bio","C1.1","Outline","Which option outlines why high temperature reduces enzyme activity?",["The active site changes shape, so the substrate no longer fits (denaturation)","The enzyme is used up in the reaction","Substrate molecules move too slowly","The enzyme turns into a different substrate"],0,"High temperature breaks the bonds holding the enzyme's tertiary structure, so the active site loses its shape and the enzyme is denatured.");
MQ("bio","D3.3","Identify","Identify the hormone that lowers blood glucose concentration.",["Insulin","Glucagon","Adrenaline","Thyroxine"],0,"Insulin, secreted by beta cells of the pancreas, causes cells to absorb glucose and the liver to store it as glycogen. Glucagon raises blood glucose.");
MQ("bio","B3.1","State","State one adaptation of alveoli for gas exchange.",["Walls one cell thick, giving a short diffusion distance","Thick muscular walls","Few capillaries","A waxy cuticle"],0,"Alveoli have very thin walls, a large surface area, a moist lining and a dense capillary network, all of which speed up diffusion.");
MQ("bio","D2.1","Distinguish","Which statement distinguishes mitosis from meiosis?",["Mitosis gives two genetically identical diploid cells; meiosis gives four genetically different haploid cells","Mitosis gives four haploid cells; meiosis gives two diploid cells","Only meiosis involves DNA replication","Mitosis only happens in gametes"],0,"Mitosis is used for growth and repair and produces identical cells. Meiosis produces gametes with half the chromosome number and new combinations of alleles.");
MQ("bio","C3.2","Identify","Identify the cells that produce antibodies.",["Plasma cells (activated B lymphocytes)","Phagocytes","Red blood cells","Platelets"],0,"Activated B lymphocytes divide into plasma cells, which secrete antibodies specific to an antigen.");
MQ("bio","C2.2","State","State the role of the myelin sheath.",["It insulates the axon and speeds up the nerve impulse (saltatory conduction)","It produces neurotransmitters","It detects stimuli","It stores calcium ions"],0,"Myelin insulates the axon so the action potential jumps between nodes of Ranvier, which is much faster than continuous conduction.");

/* ---------- Chemistry ---------- */
MQ("chem","S1.2","Define","Which option defines isotopes?",["Atoms of the same element with different numbers of neutrons","Atoms with the same mass number but different elements","Ions of the same element with different charges","Atoms of different elements with the same number of neutrons"],0,"Isotopes have the same atomic number (protons) but different mass numbers, because their neutron numbers differ.");
MQ("chem","S2.2","State","State the shape of a methane molecule.",["Tetrahedral, 109.5°","Trigonal planar, 120°","Bent, 104.5°","Linear, 180°"],0,"Methane has four bonding pairs and no lone pairs around carbon, so VSEPR predicts a tetrahedral shape with 109.5° angles.");
MQ("chem","R2.2","Explain","Which explains why a catalyst increases the rate of reaction?",["It provides an alternative pathway with a lower activation energy","It increases the kinetic energy of the particles","It increases the concentration of reactants","It shifts the equilibrium towards the products"],0,"A catalyst lowers activation energy, so a larger fraction of collisions have enough energy to react. It does not change the position of equilibrium.");
MQ("chem","R2.3","Predict","Predict the effect of increasing pressure on N₂(g) + 3H₂(g) ⇌ 2NH₃(g).",["The equilibrium shifts right, towards fewer gas molecules","The equilibrium shifts left","No change, because the catalyst controls it","Kc increases"],0,"There are 4 moles of gas on the left and 2 on the right. Le Chatelier's principle: higher pressure favours the side with fewer gas moles. Kc only changes with temperature.");
MQ("chem","R3.2","Identify","Identify what happens to the oxidising agent in a redox reaction.",["It is reduced and gains electrons","It is oxidised and loses electrons","It gains protons","It is unchanged"],0,"An oxidising agent oxidises another species by accepting its electrons, so it is itself reduced (OIL RIG).");
MQ("chem","R3.1","State","State the Brønsted–Lowry definition of an acid.",["A proton (H⁺) donor","A proton acceptor","An electron-pair acceptor","A substance that produces OH⁻ ions"],0,"Brønsted–Lowry acids donate protons; bases accept them. Electron-pair acceptors are Lewis acids.");
MQ("chem","S1.4","Calculate","Calculate the amount of substance in 9.0 g of water (M = 18.0 g mol⁻¹).",["0.50 mol","2.0 mol","162 mol","0.20 mol"],0,"n = m ÷ M = 9.0 ÷ 18.0 = 0.50 mol.");

/* ---------- Physics ---------- */
MQ("phys","A.1","State","State which of these is a vector quantity.",["Velocity","Speed","Energy","Mass"],0,"A vector has magnitude and direction. Velocity is a vector; speed, energy and mass are scalars.");
MQ("phys","A.1","Calculate","Calculate the time for a ball dropped from rest to fall 20 m (g = 10 m s⁻²; ignore air resistance).",["2.0 s","4.0 s","1.0 s","20 s"],0,"s = ½gt², so 20 = 5t², t² = 4, t = 2.0 s.");
MQ("phys","A.2","State","State Newton's third law.",["When A exerts a force on B, B exerts an equal and opposite force on A","F = ma","An object stays at rest unless a force acts","Momentum is always conserved"],0,"Newton's third law describes force pairs: equal in size, opposite in direction, of the same type, acting on different bodies.");
MQ("phys","A.3","Calculate","Calculate the kinetic energy of a 2.0 kg mass moving at 3.0 m s⁻¹.",["9.0 J","6.0 J","18 J","3.0 J"],0,"Eₖ = ½mv² = ½ × 2.0 × 3.0² = 9.0 J.");
MQ("phys","B.5","Calculate","Calculate the current through a 6.0 Ω resistor with a potential difference of 12 V across it.",["2.0 A","72 A","0.5 A","18 A"],0,"I = V ÷ R = 12 ÷ 6.0 = 2.0 A.");
MQ("phys","C.2","Calculate","Calculate the wavelength of a 500 Hz sound wave travelling at 340 m s⁻¹.",["0.68 m","1.47 m","170 000 m","0.34 m"],0,"λ = v ÷ f = 340 ÷ 500 = 0.68 m.");
MQ("phys","E.3","Identify","Identify the radiation that is most strongly ionising.",["Alpha","Beta","Gamma","All are equal"],0,"Alpha particles are large and doubly charged, so they ionise strongly but are stopped by paper.");
MQ("phys","C.5","Describe","Which describes what an observer hears as a siren moves towards them?",["A higher frequency than emitted","A lower frequency than emitted","The same frequency, but louder only","No change at all"],0,"Wavefronts are compressed in front of a moving source, so the observed frequency is higher (Doppler effect).");

/* ---------- Business Management ---------- */
MQ("biz","3.3","Calculate","Calculate total cost if fixed costs are $500 and 100 units are made at a variable cost of $3 each.",["$800","$300","$500","$1,500"],0,"Total cost = fixed costs + (variable cost per unit × quantity) = 500 + 3 × 100 = $800.");
MQ("biz","5.5","Calculate","Calculate the break-even quantity: fixed costs $1,000, price $15, variable cost $5 per unit.",["100 units","67 units","200 units","50 units"],0,"Contribution per unit = 15 − 5 = $10. Break-even = fixed costs ÷ contribution = 1,000 ÷ 10 = 100 units.");
MQ("biz","1.2","Identify","Identify the type of business entity whose owner has unlimited liability.",["Sole trader","Public limited company","Private limited company","Cooperative with limited liability"],0,"A sole trader is not legally separate from the business, so personal assets can be used to pay business debts.");
MQ("biz","2.4","Distinguish","Which correctly distinguishes Herzberg's hygiene factors from motivators?",["Hygiene factors prevent dissatisfaction; motivators create satisfaction","Hygiene factors motivate; motivators prevent dissatisfaction","Both create satisfaction equally","Hygiene factors are only about money"],0,"In Herzberg's two-factor theory, hygiene factors (pay, conditions) prevent dissatisfaction, while motivators (achievement, recognition) increase satisfaction.");
MQ("biz","3.5","State","State the formula for the current ratio.",["Current assets ÷ current liabilities","(Current assets − stock) ÷ current liabilities","Gross profit ÷ revenue × 100","Net profit ÷ capital employed × 100"],0,"Current ratio = current assets ÷ current liabilities. The acid-test ratio excludes stock.");
MQ("biz","4.5","Identify","Identify the pricing strategy that sets a high price at launch and lowers it later.",["Price skimming","Penetration pricing","Cost-plus pricing","Loss leader"],0,"Price skimming targets early adopters willing to pay more. Penetration pricing starts low to gain market share.");
MQ("biz","2.3","Identify","Identify the leadership style in which the leader makes decisions alone.",["Autocratic","Democratic","Laissez-faire","Paternalistic"],0,"Autocratic leaders make decisions without consulting employees. Democratic leaders involve employees.");

/* ---------- History ---------- */
MQ("hist","WT11","Identify","Identify the event that directly triggered the July Crisis of 1914.",["The assassination of Archduke Franz Ferdinand","The invasion of Belgium","The sinking of the Lusitania","The Zimmermann Telegram"],0,"Franz Ferdinand's assassination in Sarajevo on 28 June 1914 started the July Crisis that led to war.");
MQ("hist","WT12","Identify","Identify the US policy of 1947 that promised support to countries resisting communism.",["The Truman Doctrine","The Marshall Plan","Détente","The domino theory"],0,"The Truman Doctrine (March 1947) pledged support to free peoples resisting subjugation. The Marshall Plan gave economic aid.");
MQ("hist","WT12","State","State the year the Berlin Wall was built.",["1961","1948","1989","1953"],0,"East Germany built the Wall in August 1961 to stop emigration to the West. It fell in 1989.");
MQ("hist","WT10","Identify","Identify the policy Stalin used to collectivise Soviet agriculture.",["Collectivisation through collective farms (kolkhozes)","The New Economic Policy","Perestroika","The Great Leap Forward"],0,"Stalin forced peasants into collective farms from 1928–29. The NEP was Lenin's; the Great Leap Forward was Mao's.");
MQ("hist","PS4","Identify","Identify the 1955–56 protest sparked by Rosa Parks' arrest.",["The Montgomery Bus Boycott","The Greensboro sit-ins","The Selma marches","The Freedom Rides"],0,"Parks' arrest in December 1955 led to the year-long Montgomery Bus Boycott, which ended with a Supreme Court ruling against bus segregation.");
MQ("hist","PS4","Identify","Identify the 1960 event in which South African police shot anti-pass-law protesters.",["The Sharpeville massacre","The Soweto uprising","The Rivonia Trial","The Defiance Campaign"],0,"At Sharpeville on 21 March 1960 police killed 69 people protesting the pass laws. Soweto was in 1976.");
MQ("hist","WT8","Identify","Identify the 1930 protest Gandhi led against British salt laws.",["The Salt March","The Quit India Movement","The Amritsar Massacre","The Non-Cooperation Movement"],0,"The Salt March to Dandi in 1930 defied the British salt tax and became a model of non-violent civil disobedience.");

/* ---------- Geography ---------- */
MQ("geo","1.1","Identify","Identify the stage of the demographic transition model with high birth rates and rapidly falling death rates.",["Stage 2 (early expanding)","Stage 1 (high stationary)","Stage 4 (low stationary)","Stage 5 (declining)"],0,"In stage 2, better food supply, water and healthcare cut death rates while birth rates stay high, so natural increase is rapid. Stage 1 has both rates high; stage 4 has both low; in stage 5 the birth rate falls below the death rate.");
MQ("geo","1.2","Distinguish","Distinguish between a refugee and an internally displaced person (IDP).",["A refugee has crossed an international border; an IDP is forced from home but stays in their own country","A refugee moves for work; an IDP moves because of conflict","A refugee has permanent residency abroad; an IDP is a temporary migrant","There is no difference: both mean any forced migrant"],0,"Under the 1951 Refugee Convention a refugee is outside their country of nationality with a well-founded fear of persecution. IDPs are forcibly displaced within their own country's borders, so they keep their own government's (often weak) protection.");
MQ("geo","2.1","Define","Define the enhanced greenhouse effect.",["The increase in the natural greenhouse effect caused by human emissions of greenhouse gases","The natural trapping of infrared radiation by water vapour","The thinning of the ozone layer by CFCs","The reflection of sunlight by ice and snow"],0,"The natural greenhouse effect keeps Earth habitable. The enhanced effect is the extra warming from human-released gases such as CO₂, methane and nitrous oxide. Ozone depletion is a separate issue, and reflection of sunlight is albedo.");
MQ("geo","3.3","Distinguish","Distinguish between the views of Malthus and Boserup on population and food supply.",["Malthus: population outgrows food, causing checks such as famine. Boserup: population pressure drives new farming methods that raise food supply","Malthus: technology always keeps pace with population. Boserup: famine is inevitable","Both argued population growth always ends in famine","Malthus focused on energy and Boserup on water"],0,"Malthus (1798) said food grows arithmetically and population geometrically, so 'positive checks' follow. Boserup (1965) said 'necessity is the mother of invention': population pressure leads to intensification, so food supply rises.");
MQ("geo","4.2","Define","Define remittances.",["Money sent home by migrants to family in their country of origin","Aid sent from one government to another","Profits a TNC sends back to its headquarters","Loans from the World Bank to low-income countries"],0,"Remittances are transfers from migrants to households at home. Globally they exceed official aid to low- and middle-income countries. Government-to-government aid is bilateral aid; profits sent home by TNCs are repatriated profits.");
MQ("geo","A.1","Define","Define infiltration.",["The downward movement of water from the surface into the soil","The movement of water through rock layers deep underground","The flow of water across the ground surface","Water lost to the atmosphere from plant leaves"],0,"Infiltration is water entering the soil. Deeper movement into rock is percolation; flow over the surface is overland flow (surface runoff); loss from leaves is transpiration.");
MQ("geo","A.2","State","State what is meant by lag time on a storm hydrograph.",["The time between peak rainfall and peak discharge","The time between the start of rainfall and the end of the falling limb","The time it takes the river to return to baseflow","The time between the start of the rising limb and peak rainfall"],0,"Lag time runs from peak rainfall to peak discharge. A short lag time (steep slopes, impermeable or urban surfaces) means a 'flashy' river with higher flood risk.");
MQ("geo","B.2","Outline","Outline how longshore drift moves sediment along a coast.",["Swash carries sediment up the beach at the angle of the prevailing wind; backwash pulls it straight back down, so it zigzags along the shore","Backwash carries sediment up the beach at an angle and swash pulls it straight back","Tides carry sediment along the coast twice a day","Rip currents carry sediment offshore and drop it further along the coast"],0,"Waves approach at an angle set by the prevailing wind, so swash moves material diagonally up the beach. Backwash returns it straight down under gravity. Repeated, this moves sediment along the coast, building spits and bars.");
MQ("geo","D.1","Identify","Identify the type of plate boundary along the Mid-Atlantic Ridge.",["Constructive (divergent)","Destructive (convergent)","Conservative (transform)","Collision"],0,"At the Mid-Atlantic Ridge the North American and Eurasian plates move apart. Magma rises to fill the gap, creating new oceanic crust (sea-floor spreading), as in Iceland.");
MQ("geo","G.1","Identify","Identify the urban model made of concentric rings around the CBD.",["The Burgess model","The Hoyt sector model","The Harris and Ullman multiple nuclei model","Bid-rent theory"],0,"Burgess (1925) drew rings: CBD, zone in transition, working-class housing, middle-class housing and the commuter zone. Hoyt added sectors along transport routes; Harris and Ullman added several nuclei.");
/* ---------- French ab initio ---------- */
MQ("fr","G.1","Identify","Identify the correct passé composé: 'she went'.",["elle est allée","elle a allé","elle est allé","elle a allée"],0,"Aller takes être in the passé composé, so the past participle agrees with the subject. Elle is feminine singular, so allé takes an -e: elle est allée.");
MQ("fr","G.1","Identify","Identify the correct present tense: 'nous ___ (faire)'.",["faisons","faisez","fons","faissons"],0,"Faire is irregular: je fais, tu fais, il fait, nous faisons, vous faites, ils font.");
MQ("fr","G.2","Identify","Identify the connective that means 'however'.",["cependant","donc","parce que","ensuite"],0,"Cependant means however. Donc means so or therefore, parce que means because and ensuite means next.");
MQ("fr","I.2","Identify","Identify the correct way to say 'my sister'.",["ma sœur","mon sœur","mes sœur","ma frère"],0,"Sœur is feminine singular, so it takes ma. Mon goes before masculine nouns (and feminine nouns that start with a vowel, such as mon amie); mes is plural.");
MQ("fr","E.1","Identify","Identify the correct sentence for 'I get up at seven o'clock'.",["Je me lève à sept heures.","Je lève à sept heures.","Je me lever à sept heures.","Je suis levé sept heures."],0,"Se lever is reflexive, so it needs me: je me lève. The verb must be conjugated, not left as lever, and à is needed before a time.");
MQ("fr","P.1","Identify","Identify the correct way to say 'it's cold' (the weather).",["Il fait froid","Il est froid","C'est froid","Il a froid"],0,"Weather uses il fait: il fait froid, il fait chaud, il fait beau. Il a froid means a person feels cold; il est froid and c'est froid describe a thing.");
MQ("fr","H.1","Identify","Identify the missing word: 'Je vais au collège ___ vélo.'",["à","en","par","sur"],0,"Use à for transport you sit on or go on foot (à vélo, à pied, à cheval) and en for vehicles you get inside (en voiture, en train, en bus).");
MQ("fr","S.2","Identify","Identify the exam French students take at the end of lycée, at about 18.",["le baccalauréat (le bac)","le brevet","le collège","la rentrée"],0,"Le bac ends lycée. Le brevet is taken at about 15 at the end of collège, and la rentrée is the start of the school year.");
/* ---------- Economics ---------- */
MQ("econ","1.1","Define","Which option defines opportunity cost?",["The value of the next best alternative given up","The money price paid for a good","The total cost of all the alternatives","The cost of producing one more unit"],0,"Opportunity cost is the next best alternative forgone when a choice is made. It need not be a money cost, and only the single next best option counts, not all alternatives.");
MQ("econ","2.5","Identify","Identify the value of PED when a 10% rise in price causes a 25% fall in quantity demanded.",["−2.5 (price elastic)","−0.4 (price inelastic)","−0.25 (price inelastic)","−1 (unit elastic)"],0,"PED = %ΔQd ÷ %ΔP = −25 ÷ 10 = −2.5. Its absolute value is greater than 1, so demand is price elastic.");
MQ("econ","2.7","Outline","Which option outlines the effect of a maximum price set below equilibrium?",["Quantity demanded exceeds quantity supplied, causing a shortage","Quantity supplied exceeds quantity demanded, causing a surplus","The market clears at the new price","Producers increase output to meet demand"],0,"Below equilibrium, consumers want more and producers supply less, so there is excess demand (a shortage), often with queues and black markets.");
MQ("econ","2.8","Identify","Identify the condition for the socially optimal level of output.",["Marginal social benefit equals marginal social cost","Marginal private benefit equals marginal private cost","Total revenue equals total cost","Average cost is at its minimum"],0,"Allocative efficiency for society requires MSB = MSC. With an externality, the market produces where MPB = MPC instead, which is not socially optimal.");
MQ("econ","3.1","Distinguish","Which statement distinguishes real GDP from nominal GDP?",["Real GDP is adjusted for inflation; nominal GDP is at current prices","Real GDP includes net income from abroad; nominal GDP does not","Real GDP is per person; nominal GDP is the total","Real GDP excludes government spending"],0,"Real GDP removes the effect of price changes, so it shows changes in actual output. GNI, not real GDP, adds net income from abroad.");
MQ("econ","3.2","Identify","Identify the value of the multiplier when the marginal propensity to consume is 0.8.",["5","1.25","0.2","8"],0,"Multiplier = 1 ÷ (1 − MPC) = 1 ÷ 0.2 = 5. Each $1 of extra spending raises national income by $5.");
MQ("econ","3.5","Outline","Which option outlines how a central bank can reduce demand-pull inflation?",["Raise interest rates, making borrowing dearer and reducing consumption and investment","Cut interest rates to encourage saving","Buy government bonds to raise the money supply","Lower reserve requirements so banks lend more"],0,"Higher interest rates raise the cost of borrowing and the reward for saving, so C and I fall and aggregate demand slows. The other options are expansionary.");
MQ("econ","4.1","Identify","Country A gives up 2 units of cloth to make 1 unit of wheat; Country B gives up 4 units of cloth. Identify the comparative advantage.",["A has a comparative advantage in wheat; B in cloth","B has a comparative advantage in wheat; A in cloth","A has a comparative advantage in both goods","Neither country can gain from trade"],0,"A's opportunity cost of wheat (2 cloth) is lower than B's (4 cloth), so A should make wheat. B's opportunity cost of cloth (¼ wheat) is lower than A's (½ wheat), so B should make cloth.");
MQ("econ","4.5","Identify","Identify the effect of a depreciation of the currency.",["Exports become cheaper abroad and imports become dearer at home","Exports become dearer abroad and imports cheaper at home","Both exports and imports become cheaper","Inflation always falls"],0,"A weaker currency means foreigners need less of their own money to buy exports, while residents pay more for imports, which can cause imported inflation.");

/* ---------- Psychology ---------- */
MQ("psych","R.1","Identify","Identify the experimental design in which the same participants take part in every condition.",["Repeated measures","Independent samples","Matched pairs","Naturalistic observation"],0,"In repeated measures, each participant does all conditions, which controls participant variables but risks order effects, reduced by counterbalancing.");
MQ("psych","R.3","State","State the ethical guideline that requires participants to be told the true aim of the study afterwards.",["Debriefing","Informed consent","Confidentiality","Right to withdraw"],0,"Debriefing happens after the study: participants are told the true aim, reassured and reminded they can withdraw their data. Informed consent is given before the study.");
MQ("psych","B.1","Identify","Identify the brain structure most associated with transferring memories into long-term storage.",["Hippocampus","Amygdala","Cerebellum","Broca's area"],0,"The case of HM showed that without the hippocampus new long-term memories can't be formed. The amygdala processes emotion; the cerebellum coordinates movement; Broca's area produces speech.");
MQ("psych","B.3","Outline","Which option outlines why identical (MZ) twins are compared with non-identical (DZ) twins?",["MZ twins share all their genes and DZ twins about half, so a higher MZ concordance suggests a genetic influence","MZ twins share the same environment and DZ twins do not","DZ twins share all their genes","Twins are easy to recruit"],0,"If a trait is more concordant in MZ than DZ twins, genes are likely to play a role. Both kinds of twin usually share their environment, which is why this comparison is used.");
MQ("psych","C.1","Identify","Identify the component of the working memory model that controls attention and coordinates the other parts.",["Central executive","Phonological loop","Visuospatial sketchpad","Sensory register"],0,"The central executive directs attention and coordinates the slave systems. The sensory register belongs to the multi-store model.");
MQ("psych","C.2","Outline","Which option outlines Loftus and Palmer's (1974) finding?",["The verb in a leading question changed participants' estimates of a car's speed","Eyewitnesses are always accurate","Stress improves memory for weapons","Memories cannot be changed after the event"],0,"Participants asked how fast cars 'smashed' estimated higher speeds than those asked about 'hit', and were more likely to report broken glass: evidence for reconstructive memory.");
MQ("psych","S.1","Identify","Identify the theory that explains in-group favouritism through categorization, identification and comparison.",["Social identity theory","Social cognitive theory","Schema theory","Realistic conflict theory"],0,"Tajfel and Turner's social identity theory: people categorize, identify with their group and compare it favourably with out-groups to boost self-esteem.");
MQ("psych","S.3","Identify","Identify Berry's acculturation strategy in which a person keeps their heritage culture and also takes part in the new culture.",["Integration","Assimilation","Separation","Marginalization"],0,"Integration combines both cultures and is usually linked to the least acculturative stress. Assimilation gives up the heritage culture; separation avoids the new one; marginalization loses both.");
MQ("psych","L.1","Distinguish","Which statement distinguishes negative reinforcement from punishment?",["Negative reinforcement removes something unpleasant to increase a behaviour; punishment makes a behaviour less likely","Both make behaviour less likely","Negative reinforcement adds something unpleasant","Punishment always removes something pleasant to increase behaviour"],0,"All reinforcement, positive or negative, makes behaviour more likely. Negative reinforcement removes something unpleasant, e.g. taking a painkiller to end a headache. Punishment decreases behaviour.");

/* ---------- Mathematics: applications and interpretation ---------- */
MQ("mathai","1.2","Identify","Identify the value after 2 years of $500 invested at 4% compounded annually.",["$540.80","$540.00","$520.00","$580.00"],0,"FV = 500 × 1.04² = 540.80. Simple interest would give $540.00; compounding adds interest on the first year's interest.");
MQ("mathai","2.2","Identify","Identify the model best suited to the height of a seat on a turning Ferris wheel.",["Sinusoidal","Exponential","Linear","Logistic"],0,"Height rises and falls periodically as the wheel turns at constant speed, so a sine or cosine model fits.");
MQ("mathai","3.1","Identify","Identify the rule to find a side when you know two sides and the included angle.",["Cosine rule","Sine rule","Pythagoras' theorem","SOHCAHTOA"],0,"With two sides and the angle between them, the cosine rule a² = b² + c² − 2bc cos A gives the third side. The sine rule needs a side and its opposite angle.");
MQ("mathai","3.2","State","State how each edge of a Voronoi diagram is constructed.",["On the perpendicular bisector between two neighbouring sites","By joining two neighbouring sites","As a tangent to a circle around a site","As the line of best fit through the sites"],0,"Every point on an edge is equidistant from the two sites it separates, so it lies on their perpendicular bisector.");
MQ("mathai","4.2","Identify","Identify the median of 2, 9, 4, 7, 5, 8.",["6","5","6.5","4.5"],0,"In order: 2, 4, 5, 7, 8, 9. With six values the median is the mean of the 3rd and 4th: (5 + 7) ÷ 2 = 6.");
MQ("mathai","4.3","Outline","Which option outlines what r = 0.95 shows?",["A strong positive linear correlation","That x causes y","A weak negative correlation","That 95% of points lie on the line"],0,"r close to +1 means a strong positive linear relationship. Correlation alone never proves causation.");
MQ("mathai","4.6","Identify","Identify the degrees of freedom for a χ² test of independence on a table with 2 rows and 5 columns.",["4","10","7","3"],0,"Degrees of freedom = (rows − 1)(columns − 1) = 1 × 4 = 4.");
MQ("mathai","5.1","State","State the gradient of y = x³ at x = 2.",["12","8","6","4"],0,"dy/dx = 3x², so at x = 2 the gradient is 3 × 4 = 12.");
MQ("mathai","5.2","Identify","Identify why the trapezoidal rule gives an approximate area.",["It replaces the curve with straight line segments","It ignores the area below the x-axis","It only works for straight lines","It uses the wrong limits"],0,"Each strip's top is a straight line between two points on the curve, so it over- or under-estimates the area depending on the curvature.");

/* ---------- Environmental systems and societies ---------- */
MQ("ess","1.1","Identify","Identify the environmental value system that believes technology can solve environmental problems.",["Technocentrism","Ecocentrism","Deep ecology","Self-reliance soft ecology"],0,"Technocentrists trust human ingenuity and technology to manage environmental problems. Ecocentrists and deep ecologists put nature first and favour self-restraint.");
MQ("ess","1.2","Identify","Identify the type of system that exchanges energy but not matter with its surroundings.",["Closed system","Open system","Isolated system","Steady-state system"],0,"A closed system exchanges energy only; the Earth is close to one. Open systems exchange energy and matter; isolated systems exchange neither.");
MQ("ess","2.2","Outline","Which option outlines why energy pyramids are never inverted?",["Energy is lost as heat at each trophic level, so each level has less than the one below","Producers are always the largest organisms","Consumers store more energy than producers","Energy is recycled within each level"],0,"About 90% of energy is lost at each transfer, mainly through respiration, so the energy at each higher level is always smaller.");
MQ("ess","2.5","Identify","Identify the community that develops at the end of an ecological succession.",["Climax community","Pioneer community","Plagioclimax","Seral community"],0,"Succession ends in a stable climax community in equilibrium with the climate. A plagioclimax is succession halted by human activity.");
MQ("ess","3.3","Distinguish","Which option distinguishes in situ from ex situ conservation?",["In situ protects species in their natural habitat; ex situ protects them elsewhere, e.g. in zoos","In situ uses zoos; ex situ uses national parks","Both happen only in seed banks","Ex situ means protecting habitats; in situ means captive breeding"],0,"In situ conservation, e.g. national parks, keeps species in their habitats. Ex situ conservation, e.g. zoos and seed banks, protects them outside it.");
MQ("ess","4.4","Outline","Which option outlines why eutrophication kills fish?",["Bacteria decomposing dead algae use up the oxygen in the water","Algae poison the fish directly","The water becomes too acidic","Nitrates make the water too warm"],0,"Nutrients cause algal blooms; when the algae die, decomposing bacteria use up dissolved oxygen, so fish suffocate.");
MQ("ess","6.4","Identify","Identify the international agreement that phased out CFCs.",["Montreal Protocol","Kyoto Protocol","Paris Agreement","Ramsar Convention"],0,"The 1987 Montreal Protocol phased out CFCs and is helping the ozone layer recover. Kyoto and Paris deal with greenhouse gases; Ramsar protects wetlands.");
MQ("ess","8.1","Identify","Identify the stage of the demographic transition model with high birth rates and falling death rates.",["Stage 2","Stage 1","Stage 4","Stage 5"],0,"In stage 2 better healthcare and food lower death rates while birth rates stay high, so the population grows rapidly.");
MQ("ess","HL.a","Outline","Which option outlines the precautionary principle?",["Act to prevent harm even when scientific evidence is not yet certain","Only act once harm has been proven","Polluters must pay for the damage they cause","Economic growth should always come first"],0,"The precautionary principle puts the burden of proof on those proposing a risky activity. The polluter pays principle is a separate idea.");

/* ---------- Theory of Knowledge ---------- */
MQ("tok","C.1","Identify","Identify the classical definition of knowledge that Gettier challenged.",["Justified true belief","Certain true opinion","Shared reliable information","Verified sense data"],0,"Plato's account says knowledge is a belief that is true and justified. Gettier's 1963 cases showed a justified true belief can be true by luck.");
MQ("tok","C.2","Identify","Identify the element of the TOK knowledge framework that asks how knowledge is produced and tested.",["Methods and tools","Scope","Perspectives","Ethics"],0,"Methods and tools covers how an area makes knowledge, such as experiments or proofs. Scope is what the area covers, perspectives are the knowers' viewpoints and ethics is the moral questions.");
MQ("tok","C.2","Identify","Which type of reasoning gives a conclusion that must be true if the premises are true?",["Deductive","Inductive","Abductive","Analogical"],0,"Deduction guarantees its conclusion from true premises. Induction and abduction only make a conclusion probable or the best explanation.");
MQ("tok","O.2","Identify","Identify the idea that the language we speak shapes how we think.",["Linguistic relativity (the Sapir-Whorf hypothesis)","The intentional fallacy","Epistemic injustice","The institutional theory"],0,"Linguistic relativity says language influences thought and perception. The other options belong to the arts and politics.");
MQ("tok","O.3","Define","Which option defines epistemic injustice?",["Being wronged as a knower, e.g. not believed because of prejudice","A law that bans a book","A historian's biased choice of sources","An error in a mathematical proof"],0,"Miranda Fricker's term covers testimonial injustice (not being believed) and hermeneutical injustice (lacking the concepts to describe your experience).");
MQ("tok","A.3","Identify","Identify the philosopher who said a scientific theory must be falsifiable.",["Karl Popper","Thomas Kuhn","David Hume","René Descartes"],0,"Popper's falsifiability separates science from pseudoscience. Kuhn wrote about paradigm shifts, Hume about induction and Descartes about doubt.");
MQ("tok","A.3","Identify","Identify the thinker who described scientific revolutions as paradigm shifts.",["Thomas Kuhn","Karl Popper","Francis Bacon","Isaac Newton"],0,"Kuhn's The Structure of Scientific Revolutions (1962) described normal science, the build-up of anomalies and revolutionary paradigm shifts.");
MQ("tok","A.4","Identify","What did Gödel's incompleteness theorems show?",["Some true statements in a system can never be proved within it","Every true statement can eventually be proved","Euclid's axioms are false","Mathematics is invented, not discovered"],0,"Gödel (1931) showed that any consistent system rich enough for arithmetic contains true statements it can't prove.");
MQ("tok","X.1","Identify","Identify the word limit of the TOK essay.",["1,600 words","950 words","2,200 words","4,000 words"],0,"The TOK essay is up to 1,600 words. The exhibition commentary is up to 950 words and the Extended Essay up to 4,000.");
MQ("tok","X.1","Identify","How many objects does a TOK exhibition need?",["Three","One","Five","Six"],0,"The exhibition presents three objects linked to one of the 35 IA prompts, each with a commentary.");
/* ---------- English A: Literature ---------- */
MQ("lit","R.1","Identify","Identify the term for a character who contrasts with another to highlight their qualities.",["Foil","Confidant","Stock character","Antagonist"],0,"A foil sets off another character by contrast, e.g. Laertes and Hamlet. A confidant hears secrets, a stock character is a familiar type and an antagonist opposes the hero.");
MQ("lit","R.2","Identify","What does the green light symbolize in The Great Gatsby?",["Gatsby's longing for Daisy and the American Dream","The danger of driving at night","Gatsby's wealth from bootlegging","Envy between East Egg and West Egg"],0,"The light at the end of Daisy's dock stands for Gatsby's hope and longing, always just out of reach.");
MQ("lit","R.3","Identify","Identify the kind of poem written to mourn someone's death.",["Elegy","Ode","Aubade","Epithalamium"],0,"An elegy mourns the dead. An ode praises, an aubade greets the dawn and an epithalamium celebrates a wedding.");
MQ("lit","T.1","Identify","Identify the oldest of these works.",["The Epic of Gilgamesh","The Odyssey","The Aeneid","Beowulf"],0,"Gilgamesh goes back to Mesopotamian poems of about 2100 BCE. The Odyssey is from about 700 BCE, the Aeneid from 19 BCE, and Beowulf is Old English.");
MQ("lit","T.2","Identify","In The Canterbury Tales, why are the pilgrims telling stories?",["A storytelling contest to win a free meal","To pass a trial set by the King","To raise money for the cathedral","To confess their sins to the Pardoner"],0,"The Host proposes a contest: the best tale earns a free supper on their return.");
MQ("lit","T.3","Identify","Identify the novel written as a series of letters and diary entries.",["Dracula","Great Expectations","Jane Eyre","Middlemarch"],0,"Dracula is epistolary: letters, diaries and newspaper cuttings. The others are told by a narrator.");
MQ("lit","T.4","Identify","Identify the novel Chinua Achebe wrote partly in answer to Heart of Darkness.",["Things Fall Apart","Half of a Yellow Sun","The Famished Road","Americanah"],0,"Achebe's Things Fall Apart (1958) tells colonialism from an Igbo perspective. The other three are by Adichie and Okri.");
MQ("lit","I.2","Define","Which option defines anagnorisis?",["The moment a character recognizes the truth","The tragic hero's fatal flaw","The release of emotion in the audience","The hero's excessive pride"],0,"Anagnorisis is recognition, e.g. Oedipus learning who he is. The others are hamartia, catharsis and hubris.");
MQ("lit","W.1","Identify","Identify the author of The Metamorphosis, in which Gregor Samsa wakes up as an insect.",["Franz Kafka","Albert Camus","Fyodor Dostoevsky","Gabriel García Márquez"],0,"Kafka wrote The Metamorphosis in German (1915).");
MQ("lit","C.2","Identify","How long is the HL essay in English A: Literature?",["1,200 to 1,500 words","950 words","1,600 words","4,000 words"],0,"The HL essay is 1,200 to 1,500 words on one work. 1,600 is the TOK essay and 4,000 is the extended essay.");
/* ---------- Spanish ab initio ---------- */
MQ("es","I.1","Identify","Identify the correct sentence for 'I am tired' (right now).",["Estoy cansado.","Soy cansado.","Tengo cansado.","Hago cansado."],0,"Temporary states take estar: estoy cansado. Ser is for permanent traits, tener for age and some feelings, such as tengo hambre.");
MQ("es","I.1","Identify","Identify the correct way to say 'I am 15 years old'.",["Tengo quince años.","Soy quince años.","Estoy quince años.","Tengo quince anos."],0,"Age uses tener: tengo quince años. Without the tilde, años becomes anos, a very different word.");
MQ("es","I.2","Identify","Identify the correct way to say 'my parents'.",["mis padres","mi padres","mis padre","mía padres"],0,"Mi becomes mis before a plural noun, and padres is plural.");
MQ("es","I.3","Identify","Identify the correct way to say 'I like apples'.",["Me gustan las manzanas.","Me gusta las manzanas.","Yo gusto las manzanas.","Me gustan manzanas."],0,"Gustar agrees with the thing liked: plural manzanas needs gustan, and Spanish keeps the article: las manzanas.");
MQ("es","E.1","Identify","Identify the correct sentence for 'I get up at seven'.",["Me levanto a las siete.","Levanto a las siete.","Me levanto en las siete.","Me levanta a las siete."],0,"Levantarse is reflexive, so it needs me, and clock times take a las.");
MQ("es","E.3","Identify","Identify the preterite form of ir for 'I went'.",["fui","iba","voy","iré"],0,"Fui is the preterite. Iba is the imperfect (I used to go), voy is the present and iré the future.");
MQ("es","H.1","Identify","Identify the missing word: 'Voy al colegio ___ pie.'",["a","en","por","de"],0,"On foot is a pie. Vehicles take en: en coche, en autobús.");
MQ("es","H.4","Identify","Identify the word used for 'computer' in Spain.",["el ordenador","la computadora","el portátil","la pantalla"],0,"Spain says el ordenador; most of Latin America says la computadora. El portátil is a laptop and la pantalla a screen.");
MQ("es","P.1","Identify","Identify the correct way to say 'it's hot' (the weather).",["Hace calor.","Es calor.","Está calor.","Tiene calor."],0,"Weather uses hace: hace calor, hace frío, hace sol. Tengo calor means I feel hot.");
MQ("es","G.4","Identify","Identify the right word: 'Este regalo es ___ ti.'",["para","por","a","de"],0,"Para marks the recipient: es para ti (it's for you). Por is for cause, exchange and movement through.");
/* ---------- Global Politics ---------- */
MQ("glopo","C.1","Identify","Identify the term Joseph Nye used for getting what you want through attraction rather than force.",["Soft power","Hard power","Sharp power","Structural power"],0,"Soft power works through culture, values and policies others admire. Hard power uses coercion; sharp power uses manipulation and censorship.");
MQ("glopo","C.1","Identify","Identify the 1648 settlement usually seen as founding the idea of state sovereignty.",["The Peace of Westphalia","The Treaty of Versailles","The Congress of Vienna","The Treaty of Rome"],0,"The Peace of Westphalia ended the Thirty Years' War and set out the principle that states rule their own territory without outside interference.");
MQ("glopo","C.2","Identify","Which type of authority did Max Weber link to a leader's personal qualities?",["Charismatic","Traditional","Legal-rational","Bureaucratic"],0,"Charismatic authority rests on the leader's personality. Traditional authority rests on custom, and legal-rational authority on rules and offices.");
MQ("glopo","C.3","Identify","How many permanent members of the UN Security Council hold a veto?",["Five","Three","Ten","Fifteen"],0,"The P5 (China, France, Russia, the UK and the USA) hold a veto. The Council has 15 members in all; the other ten are elected for two years.");
MQ("glopo","C.4","Identify","Identify the theory that says states seek power and security in an anarchic international system.",["Realism","Liberalism","Constructivism","Marxism"],0,"Realism stresses power, security and anarchy. Liberalism stresses cooperation, constructivism ideas and norms, and Marxism class and capitalism.");
MQ("glopo","R.1","Identify","Identify the year the UN adopted the Universal Declaration of Human Rights.",["1948","1945","1966","1989"],0,"The UDHR was adopted on 10 December 1948. The UN was founded in 1945, the two human rights covenants date from 1966, and the Convention on the Rights of the Child from 1989.");
MQ("glopo","R.2","Identify","Identify the thinker behind the 'veil of ignorance'.",["John Rawls","Robert Nozick","Isaiah Berlin","John Stuart Mill"],0,"Rawls's thought experiment asks us to choose rules without knowing our place in society. Berlin wrote on negative and positive liberty.");
MQ("glopo","D.1","Identify","Which three things does the Human Development Index combine?",["Health, education and income","GDP, inflation and unemployment","Literacy, democracy and trade","Life expectancy, emissions and debt"],0,"The HDI combines life expectancy, years of schooling and GNI per capita.");
MQ("glopo","P.1","Identify","Identify Johan Galtung's term for harm caused by unjust social structures.",["Structural violence","Direct violence","Cultural violence","Negative peace"],0,"Structural violence is built into systems such as poverty and discrimination. Direct violence has an identifiable attacker, and cultural violence justifies the other two.");
MQ("glopo","P.2","Identify","Identify the 1998 agreement that largely ended the Troubles in Northern Ireland.",["The Good Friday Agreement","The Dayton Agreement","The Oslo Accords","The Camp David Accords"],0,"The Good Friday (Belfast) Agreement set up power-sharing. Dayton ended the Bosnian war, Oslo was Israeli-Palestinian and Camp David led to Egypt-Israel peace.");
/* ---------- Sports, Exercise and Health Science ---------- */
MQ("sehs","A.1","Identify","Identify the equation for cardiac output.",["Heart rate × stroke volume","Stroke volume ÷ heart rate","Breathing rate × tidal volume","Heart rate × blood pressure"],0,"Cardiac output is the blood pumped per minute: heart rate × stroke volume. Breathing rate × tidal volume is minute ventilation.");
MQ("sehs","A.2","Identify","Identify the energy system that mainly fuels a 100 m sprint.",["The ATP-PC system","The aerobic system","The anaerobic glycolytic system","The Krebs cycle"],0,"The ATP-PC system supplies energy fastest, for about 10 seconds of maximal effort.");
MQ("sehs","A.3","Identify","Identify the training principle that says fitness is lost when training stops.",["Reversibility","Specificity","Progressive overload","Variety"],0,"Reversibility: use it or lose it. Specificity matches training to the sport, and overload means working harder than usual.");
MQ("sehs","B.1","Identify","Identify the type of joint at the knee.",["Hinge","Ball and socket","Pivot","Saddle"],0,"The knee is a hinge joint, allowing flexion and extension. The hip and shoulder are ball-and-socket joints.");
MQ("sehs","B.1","Identify","Identify the type of contraction when the quadriceps lengthen under tension as you lower into a squat.",["Eccentric","Concentric","Isometric","Isokinetic"],0,"Lengthening under tension is eccentric. Concentric contractions shorten, and isometric ones don't change length.");
MQ("sehs","B.2","Identify","Identify Newton's law shown when a sprinter pushes back on the blocks and is driven forward.",["The third law","The first law","The second law","The law of gravitation"],0,"Every action has an equal and opposite reaction: the blocks push the sprinter forward.");
MQ("sehs","B.3","Identify","Which injury is damage to a ligament?",["A sprain","A strain","A fracture","A contusion"],0,"A sprain affects a ligament; a strain affects a muscle or tendon; a fracture is a broken bone and a contusion is a bruise.");
MQ("sehs","C.2","Identify","Identify the stage of learning in which a skill becomes automatic.",["Autonomous","Cognitive","Associative","Diversification"],0,"In Fitts and Posner's model, the autonomous stage is automatic. The cognitive stage comes first and the associative stage second.");
MQ("sehs","C.4","Identify","Identify the theory that says performance is best at a moderate level of arousal.",["The inverted-U hypothesis","Drive theory","Catastrophe theory","Attribution theory"],0,"The inverted-U hypothesis predicts peak performance at moderate arousal. Drive theory predicts a straight-line rise.");
MQ("sehs","C.4","Identify","Identify which of these is a symptom of somatic anxiety.",["Butterflies in the stomach","Worrying about losing","Negative thoughts","Poor concentration"],0,"Somatic anxiety is physical: butterflies, sweating, a racing heart. The others are cognitive symptoms.");
/* ---------- Visual Arts ---------- */
MQ("va","F.1","Identify","Identify the technique of painting on wet lime plaster.",["Fresco","Encaustic","Gouache","Impasto"],0,"Fresco binds pigment into wet plaster, as in the Sistine Chapel. Encaustic uses hot wax, gouache is opaque watercolour and impasto is thick paint.");
MQ("va","F.2","Identify","Identify the type of sculpture made by removing material, e.g. carving stone.",["Subtractive","Additive","Assemblage","Casting"],0,"Subtractive sculpture takes material away. Additive builds it up (e.g. modelling clay), assemblage combines found objects and casting pours material into a mould.");
MQ("va","F.3","Identify","Which setting gives a shallow depth of field, blurring the background?",["A wide aperture","A fast shutter speed","A small aperture","A long exposure"],0,"A wide aperture (small f-number) narrows the depth of field. A small aperture keeps more in focus; shutter speed controls motion blur.");
MQ("va","E.1","Identify","Identify the formal element that describes how light or dark something is.",["Tone","Texture","Line","Shape"],0,"Tone (or value) is lightness or darkness. Texture is surface quality, line is a mark and shape is a flat area.");
MQ("va","E.3","Identify","Identify the complementary colour of blue.",["Orange","Green","Purple","Yellow"],0,"Complementary colours sit opposite each other on the colour wheel: blue and orange, red and green, yellow and purple.");
MQ("va","E.3","Identify","What is a tint?",["A colour mixed with white","A colour mixed with black","A colour mixed with grey","A colour mixed with its complement"],0,"A tint adds white and a shade adds black. Adding grey makes a tone.");
MQ("va","H.1","Identify","Identify the movement that showed objects from several viewpoints at once.",["Cubism","Impressionism","Surrealism","Pop art"],0,"Cubism, led by Picasso and Braque, broke objects into geometric planes seen from different angles.");
MQ("va","H.1","Identify","Identify the anti-art movement behind Duchamp's Fountain (1917).",["Dada","Fauvism","Futurism","Minimalism"],0,"Dada rejected reason and tradition during the First World War, using absurdity and readymades.");
MQ("va","H.2","Identify","Who painted The Starry Night?",["Vincent van Gogh","Claude Monet","Paul Cézanne","Edvard Munch"],0,"Van Gogh painted The Starry Night in 1889. Munch painted The Scream and Monet the Water Lilies.");
MQ("va","C.1","Identify","Identify the first stage of Feldman's method of art criticism.",["Description","Analysis","Interpretation","Judgement"],0,"Feldman's method goes describe, analyse, interpret, then judge.");
/* ---------- Design Technology ---------- */
MQ("dt","A.1","Identify","Identify the study of human body measurements used in design.",["Anthropometrics","Ergonomics","Biomechanics","Proxemics"],0,"Anthropometrics is the data on body sizes. Ergonomics is the wider study of how people interact with products, and proxemics is the study of personal space.");
MQ("dt","A.1","Identify","Designers often design for which range of a population?",["5th to 95th percentile","0 to 100th percentile","25th to 75th percentile","50th percentile only"],0,"The 5th to 95th percentile covers 90% of users. Covering everyone is impractical, and the average (50th percentile) fits almost nobody well.");
MQ("dt","A.2","Identify","Identify the property that describes a material's ability to absorb energy without fracturing.",["Toughness","Hardness","Brittleness","Density"],0,"Toughness is resistance to fracture under impact. Hardness resists scratching, brittle materials snap easily and density is mass per unit volume.");
MQ("dt","A.2","Identify","Which material changes colour with temperature?",["Thermochromic pigment","Photochromic material","Piezoelectric material","Shape memory alloy"],0,"Thermochromic pigments react to heat. Photochromic materials react to light, piezoelectric materials make electricity under pressure and shape memory alloys return to a set shape when heated.");
MQ("dt","A.2","Identify","Identify the type of plastic that can be reheated and reshaped many times.",["Thermoplastic","Thermosetting plastic","Composite","Elastomer"],0,"Thermoplastics soften each time they're heated, so they can be recycled. Thermosets set permanently the first time.");
MQ("dt","A.3","Identify","Identify the model that looks like the final product but doesn't work.",["An appearance model","A working prototype","A sketch model","A virtual model"],0,"An appearance model shows the exact look for feedback and marketing. A working prototype functions, and a sketch model is quick and rough.");
MQ("dt","B.2","Identify","Which process is best for making millions of identical plastic bottle caps?",["Injection moulding","Vacuum forming","Laser cutting","3D printing"],0,"Injection moulding has high set-up costs but makes identical parts very quickly and cheaply in huge numbers. 3D printing is slow for large quantities.");
MQ("dt","B.2","Identify","Identify the scale of production used by a bakery making 200 loaves before switching to rolls.",["Batch production","One-off production","Mass production","Continuous flow production"],0,"Batch production makes a set number of identical items, then switches. Continuous flow never stops, as in oil refining.");
MQ("dt","C.1","Identify","Identify the term for designing a product to wear out or go out of date after a set time.",["Planned obsolescence","Design for disassembly","Life cycle assessment","Upcycling"],0,"Planned obsolescence makes customers buy replacements. Design for disassembly does the opposite, making products easy to repair and recycle.");
MQ("dt","C.2","Identify","An innovation that creates a new market and displaces existing products is called:",["Disruptive innovation","Incremental innovation","Market pull","Technology push"],0,"Disruptive innovations, like streaming replacing DVDs, push out the old market. Incremental innovation makes small improvements to existing products.");
MQ("dt","C.3","Identify","Identify the Japanese term for continuous improvement in small steps.",["Kaizen","Kanban","Poka-yoke","Just in time"],0,"Kaizen means continuous improvement. Kanban is a signalling system for stock, poka-yoke is mistake-proofing and just in time delivers parts as they're needed.");
/* ---------- Philosophy ---------- */
MQ("phil","C.1","Identify","Whose theory says personal identity depends on memory and consciousness?",["John Locke","David Hume","René Descartes","Thomas Reid"],0,"Locke tied identity to consciousness reaching back through memory. Hume saw the self as a bundle of perceptions, and Reid criticized Locke with the brave officer objection.");
MQ("phil","C.2","Identify","Identify the thought experiment in which someone follows rules to answer in Chinese without understanding Chinese.",["The Chinese room","Mary's room","The brain in a vat","The Turing test"],0,"Searle's Chinese room (1980) argues that manipulating symbols (syntax) isn't understanding (semantics).");
MQ("phil","C.3","Identify","Identify the view that free will and determinism can both be true.",["Compatibilism","Hard determinism","Libertarianism","Fatalism"],0,"Compatibilists, such as Hume, say we act freely when we act on our own desires without being forced, even if those desires are caused.");
MQ("phil","C.3","Identify","Which philosopher wrote that existence precedes essence?",["Jean-Paul Sartre","Thomas Hobbes","Immanuel Kant","Plato"],0,"Sartre argued there is no fixed human nature: we exist first and define ourselves through our choices.");
MQ("phil","O.2","Identify","Identify the view that all knowledge comes from experience.",["Empiricism","Rationalism","Idealism","Foundationalism"],0,"Empiricists such as Locke and Hume say knowledge comes from the senses. Rationalists say some knowledge comes from reason alone.");
MQ("phil","O.2","Identify","Gettier cases challenge which definition of knowledge?",["Justified true belief","Knowledge as perception","Knowledge as reliable process","Knowledge as coherence"],0,"Gettier (1963) showed that a justified true belief can be true only by luck, so it may not be knowledge.");
MQ("phil","O.3","Identify","Identify the theory that the right act produces the greatest happiness for the greatest number.",["Utilitarianism","Kantian ethics","Virtue ethics","Divine command theory"],0,"Utilitarianism (Bentham, Mill) judges actions by their consequences for happiness.");
MQ("phil","O.4","Identify","The argument that God is that than which nothing greater can be conceived is:",["The ontological argument","The cosmological argument","The design argument","The moral argument"],0,"Anselm's ontological argument reasons from the concept of God to God's existence, without appealing to experience.");
MQ("phil","O.5","Identify","Who argued that a scientific theory must be falsifiable?",["Karl Popper","Thomas Kuhn","Francis Bacon","Paul Feyerabend"],0,"Popper proposed falsifiability as the line between science and non-science. Kuhn wrote about paradigm shifts.");
MQ("phil","O.6","Identify","Identify the philosopher who proposed the veil of ignorance.",["John Rawls","Thomas Hobbes","John Locke","Robert Nozick"],0,"Rawls (A Theory of Justice, 1971) asks us to choose principles of justice without knowing our place in society.");
MQ("phil","M.1","Identify","Attacking the person instead of their argument is called:",["Ad hominem","Straw man","Begging the question","Red herring"],0,"An ad hominem attacks the arguer. A straw man misrepresents the argument, and begging the question assumes the conclusion.");
/* ---------- Digital Society ---------- */
MQ("ds","2.1","Identify","The gap between people who have access to digital technology and those who don't is called:",["The digital divide","The filter bubble","Net neutrality","The attention economy"],0,"The digital divide is unequal access to technology and digital skills, often linked to income, location, age or gender.");
MQ("ds","3.1","Identify","Identify the EU law, in force since 2018, that protects personal data.",["GDPR","CCPA","COPPA","The Digital Services Act"],0,"The General Data Protection Regulation gives people in the EU rights over their data. The CCPA is Californian and COPPA protects US children under 13.");
MQ("ds","3.1","Identify","Data about data, such as the time and location of a photo, is called:",["Metadata","Big data","Biometric data","Open data"],0,"Metadata describes other data. Combined, it can reveal a person's routines and relationships.");
MQ("ds","3.2","Identify","When algorithms show you only content that matches your views, you are in a:",["Filter bubble","Data breach","Botnet","Sandbox"],0,"Eli Pariser coined 'filter bubble' for the personalized world algorithms build around each user.");
MQ("ds","3.4","Identify","False information spread deliberately to deceive is called:",["Disinformation","Misinformation","Satire","Clickbait"],0,"Disinformation is deliberate. Misinformation is false information shared by mistake.");
MQ("ds","3.5","Identify","Identify the attack that tricks people into giving away passwords with fake messages.",["Phishing","DDoS","Ransomware","A worm"],0,"Phishing uses fake emails or texts. A DDoS floods a server, ransomware locks files and a worm spreads by itself.");
MQ("ds","3.5","Identify","Which technology scrambles data so it can't be read without a key?",["Encryption","Compression","Caching","Routing"],0,"Encryption keeps data private even if it's intercepted. Compression makes files smaller.");
MQ("ds","3.6","Identify","Identify the type of AI in which a system learns patterns from large amounts of data.",["Machine learning","An expert system","A rule-based program","A spreadsheet"],0,"Machine learning finds patterns in data instead of following fixed rules. Expert systems follow rules written by humans.");
MQ("ds","3.6","Identify","When an AI chatbot confidently states something false, it's called a:",["Hallucination","Deepfake","Bug report","Captcha"],0,"Chatbots predict likely-sounding words rather than checking facts, so they can 'hallucinate'.");
MQ("ds","3.7","Identify","The uneasy feeling caused by robots that look almost, but not quite, human is the:",["Uncanny valley","Turing test","Trolley problem","Singularity"],0,"Masahiro Mori described the uncanny valley in 1970.");
MQ("ds","4.1","Identify","Short-term, app-based work such as food delivery is part of the:",["Gig economy","Circular economy","Command economy","Black economy"],0,"In the gig economy, workers take flexible tasks through apps, often without job security or benefits.");
/* ---------- Film ---------- */
MQ("film","R.1","Identify","Everything placed in front of the camera, such as setting, props and costume, is called:",["Mise-en-scène","Montage","Cinematography","Diegesis"],0,"Mise-en-scène is French for 'putting in the scene'. Montage is editing and cinematography is camera and lighting.");
MQ("film","R.1","Identify","Dark lighting with strong contrast and deep shadows is called:",["Low-key lighting","High-key lighting","Fill lighting","Natural lighting"],0,"Low-key lighting is typical of horror and film noir. High-key lighting is bright and even.");
MQ("film","R.2","Identify","Which shot makes a character look powerful by filming from below?",["A low-angle shot","A high-angle shot","A bird's-eye view","An eye-level shot"],0,"Looking up at a subject makes them seem dominant. A high angle looks down and makes them seem weak.");
MQ("film","R.2","Identify","A tilted camera that makes the horizon slant is a:",["Dutch angle","Dolly zoom","Whip pan","Tracking shot"],0,"A Dutch (canted) angle creates unease. A dolly zoom stretches the background, as in Vertigo.");
MQ("film","R.3","Identify","Keeping the camera on one side of an imaginary line between characters follows the:",["180-degree rule","Rule of thirds","30-degree rule","Kuleshov effect"],0,"The 180-degree rule keeps screen direction consistent so the audience isn't confused.");
MQ("film","R.3","Identify","Cutting between two events happening at the same time is called:",["Cross-cutting","A jump cut","A dissolve","A match cut"],0,"Cross-cutting (parallel editing) builds tension, e.g. a rescue racing against danger.");
MQ("film","R.4","Identify","Music that the characters can't hear is:",["Non-diegetic sound","Diegetic sound","Foley","Room tone"],0,"Non-diegetic sound exists only for the audience, like the score. Diegetic sound comes from the film's world.");
MQ("film","R.4","Identify","Everyday sounds such as footsteps, recreated in a studio, are called:",["Foley","Walla","ADR","Ambience"],0,"Foley is named after Jack Foley. ADR re-records dialogue, and walla is background crowd murmur.");
MQ("film","C.2","Identify","Which movement used real locations and non-professional actors after the Second World War?",["Italian Neorealism","German Expressionism","The French New Wave","Soviet Montage"],0,"Neorealist films such as Bicycle Thieves showed the lives of ordinary, poor Italians.");
MQ("film","C.3","Identify","The idea that the director is the main author of a film is:",["Auteur theory","Genre theory","Reception theory","Formalism"],0,"Auteur theory came from French critics of the 1950s at Cahiers du cinéma.");
MQ("film","P.2","Identify","A series of drawings showing each planned shot is a:",["Storyboard","Call sheet","Treatment","Shot list"],0,"A storyboard plans the visuals. A shot list is written, and a call sheet tells cast and crew when to arrive.");
/* ---------- Music ---------- */
MQ("music","F.1","Identify","A single melody line with no accompaniment has which texture?",["Monophonic","Homophonic","Polyphonic","Heterophonic"],0,"Monophonic means one line. Homophonic is melody with chords, and polyphonic is several independent lines.");
MQ("music","F.1","Identify","Which term means gradually getting louder?",["Crescendo","Diminuendo","Sforzando","Staccato"],0,"Crescendo means growing louder. Diminuendo is getting softer, sforzando is a sudden accent and staccato is short and detached.");
MQ("music","F.2","Identify","Which cadence (chord V to I) sounds finished?",["Perfect cadence","Imperfect cadence","Interrupted cadence","Plagal cadence"],0,"A perfect cadence (V–I) sounds final. An imperfect cadence ends on V and sounds unfinished; plagal is IV–I.");
MQ("music","F.2","Identify","A scale with five notes per octave is:",["Pentatonic","Chromatic","Whole-tone","Major"],0,"The pentatonic scale is used in folk music worldwide. The chromatic scale has all twelve semitones.");
MQ("music","F.3","Identify","Which Italian tempo marking means 'at a walking pace'?",["Andante","Allegro","Presto","Largo"],0,"Andante comes from andare, 'to walk'. Allegro is fast, presto very fast and largo very slow.");
MQ("music","F.3","Identify","Accenting the off-beats is called:",["Syncopation","Ostinato","Hemiola","Rubato"],0,"Syncopation gives jazz, funk and reggae their groove. An ostinato is a repeated pattern.");
MQ("music","F.3","Identify","A piece in three sections, A B A, is in:",["Ternary form","Binary form","Rondo form","Strophic form"],0,"Ternary form returns to A after a contrasting B. Binary is AB and rondo is ABACA.");
MQ("music","F.4","Identify","Which instrument family includes the oboe and the bassoon?",["Woodwind","Brass","Strings","Percussion"],0,"The oboe and bassoon are double-reed woodwind instruments.");
MQ("music","A.2","Identify","Bach, Handel and Vivaldi belong to which period?",["Baroque","Classical","Romantic","Renaissance"],0,"The Baroque period ran from about 1600 to 1750. Mozart and Haydn are Classical.");
MQ("music","A.3","Identify","Music heard by the audience but not by the characters in a film is:",["Non-diegetic","Diegetic","Incidental","Ambient"],0,"Non-diegetic music, such as the score, exists outside the film's world.");
MQ("music","A.4","Identify","Reusing a section of an existing recording in a new track is called:",["Sampling","Panning","Compression","Quantizing"],0,"Sampling is central to hip-hop and electronic music. Panning places sounds left or right.");
/* ---------- General knowledge (just for fun) ---------- */
MQ("gk","R.1","Identify","Riddle: What has cities but no houses, forests but no trees, and water but no fish?",["A map","A snow globe","A dream","A painting of a farm"],0,"A map shows cities, forests and rivers without any of the real things in them.");
MQ("gk","M.2","Identify","Identify the actor who played Iron Man in the Marvel films.",["Robert Downey Jr.","Chris Evans","Chris Hemsworth","Mark Ruffalo"],0,"Robert Downey Jr. played Tony Stark from Iron Man (2008) to Avengers: Endgame (2019). Chris Evans played Captain America, Chris Hemsworth Thor and Mark Ruffalo the Hulk.");
MQ("gk","S.1","Identify","Identify the band Freddie Mercury sang with.",["Queen","The Rolling Stones","Led Zeppelin","The Who"],0,"Freddie Mercury fronted Queen from 1970 until his death in 1991. Mick Jagger sings for the Rolling Stones, Robert Plant sang for Led Zeppelin and Roger Daltrey for The Who.");
MQ("gk","V.1","Identify","Identify Pikachu's type.",["Electric","Normal","Fire","Psychic"],0,"Pikachu is an Electric-type Pokémon: the name comes from Japanese pika (a sparkle) and chū (a mouse's squeak).");
MQ("gk","W.2","Identify","Identify the capital of Australia.",["Canberra","Sydney","Melbourne","Perth"],0,"Canberra was purpose-built as the capital, as a compromise between rivals Sydney and Melbourne. Parliament moved there in 1927.");
MQ("gk","W.3","Identify","Identify the planet with the most known moons.",["Saturn","Jupiter","Uranus","Neptune"],0,"Saturn has the most known moons, well over 200 after many small ones were found in 2023 and 2025, ahead of Jupiter.");
MQ("gk","F.2","State","State how many players each football (soccer) team has on the pitch.",["11","10","9","12"],0,"Each side fields 11 players, including the goalkeeper.");

/* ---------- English A: Language and Literature ---------- */
MQ("eng","R.1","Identify","Identify the device in 'The wind howled through the empty streets'.",["Personification","Simile","Hyperbole","Oxymoron"],0,"Howling is something an animal does, so the wind is given a living quality: personification. There is no 'like' or 'as' (simile), no exaggeration (hyperbole) and no contradictory pairing (oxymoron).");
MQ("eng","R.1","Identify","Identify the device in 'deafening silence'.",["Oxymoron","Paradox","Antithesis","Onomatopoeia"],0,"An oxymoron puts two contradictory words side by side. A paradox is a whole statement that seems self-contradictory; antithesis balances opposing ideas in parallel clauses.");
MQ("eng","R.2","Identify","Identify the narrative perspective of a story told with 'you' as the protagonist.",["Second person","First person","Third-person limited","Third-person omniscient"],0,"Second-person narration addresses the protagonist as 'you', drawing the reader into the action.");
MQ("eng","R.3","Identify","Identify the rhyme scheme of a Petrarchan octave.",["ABBAABBA","ABABCDCD","AABBCCDD","ABCABCAB"],0,"A Petrarchan sonnet opens with an octave rhyming ABBAABBA, then a sestet (often CDECDE or CDCDCD) after the volta.");
MQ("eng","R.4","Identify","Identify the term for a character's speech, alone on stage, revealing their thoughts.",["Soliloquy","Aside","Monologue","Dialogue"],0,"A soliloquy is spoken alone, to oneself. A monologue is a long speech to other characters; an aside is a brief remark to the audience.");
MQ("eng","T.2","Identify","Identify the literary movement associated with Wordsworth and Coleridge's Lyrical Ballads (1798).",["Romanticism","Modernism","The Enlightenment","Realism"],0,"Lyrical Ballads is often taken as the start of English Romanticism: everyday language, nature, emotion and imagination.");
MQ("eng","T.3","State","State how long the Individual Oral lasts.",["15 minutes","10 minutes","20 minutes","30 minutes"],0,"The IO lasts 15 minutes: 10 minutes of speaking followed by 5 minutes of questions from the teacher.");
MQ("eng","I.1","Identify","Identify the genre that follows a young protagonist's growth to maturity.",["Bildungsroman","Picaresque","Epistolary novel","Satire"],0,"A Bildungsroman (coming-of-age novel) traces the protagonist's moral and psychological growth, as in Jane Eyre or Great Expectations.");
MQ("eng","I.2","Identify","Identify the text that Jean Rhys's Wide Sargasso Sea responds to.",["Jane Eyre","Wuthering Heights","Rebecca","Great Expectations"],0,"Wide Sargasso Sea (1966) tells the story of Bertha Mason, the 'madwoman in the attic' of Charlotte Brontë's Jane Eyre, from a postcolonial perspective.");
MQ("eng","L.1","Identify","Identify the opening paragraph of a news article that summarises the key facts.",["The lead (lede)","The byline","The standfirst","The masthead"],0,"The lead gives the most important facts (who, what, where, when, why) first, following the inverted pyramid.");
MQ("eng","L.2","Identify","Identify the appeal used in 'As a doctor with 20 years' experience, I can tell you…'.",["Ethos","Pathos","Logos","Kairos"],0,"The speaker establishes credibility and authority: an appeal to ethos.");
MQ("eng","L.2","Identify","Identify the fallacy in 'If we let students choose their seats, soon they'll be choosing their own grades.'",["Slippery slope","Straw man","Ad hominem","False dilemma"],0,"A slippery slope claims one small step will inevitably lead to an extreme outcome, without evidence for the chain of events.");
MQ("eng","L.3","Identify","Identify the shot that shows a subject from directly above.",["Bird's-eye view","Low angle","Dutch angle","Close-up"],0,"A bird's-eye view looks straight down, often making the subject seem small or vulnerable.");
MQ("eng","L.4","Identify","Identify the technique in the headline 'Mistakes were made'.",["Agentless passive voice","Euphemism","Hyperbole","Nominalisation"],0,"The passive voice without an agent hides who made the mistakes, avoiding responsibility.");
MQ("eng","W.1","Identify","Identify the play in which a character says 'Out, damned spot!'",["Macbeth","Hamlet","Othello","King Lear"],0,"Lady Macbeth says it while sleepwalking in Act 5, Scene 1, trying to wash imagined blood from her hands: a sign of her guilt.");
MQ("eng","W.2","Identify","Identify the narrator of The Great Gatsby.",["Nick Carraway","Jay Gatsby","Daisy Buchanan","Tom Buchanan"],0,"Nick Carraway narrates in the first person, as both participant and observer; readers debate how reliable he is.");
MQ("eng","W.3","Identify","Identify the poet of 'Dulce et Decorum Est'.",["Wilfred Owen","Siegfried Sassoon","Rupert Brooke","Isaac Rosenberg"],0,"Wilfred Owen wrote it in 1917, attacking 'the old Lie' that it is sweet and fitting to die for one's country.");
MQ("eng","W.4","Identify","Identify the author of One Hundred Years of Solitude.",["Gabriel García Márquez","Isabel Allende","Jorge Luis Borges","Mario Vargas Llosa"],0,"Gabriel García Márquez (Colombia) published it in 1967; it is a landmark of magical realism.");
MQ("eng","C.1","Identify","Identify which of these is one of the seven key concepts of IB English A.",["Transformation","Ambiguity","Symbolism","Tone"],0,"The seven concepts are identity, culture, creativity, communication, perspective, transformation and representation.");
MQ("eng","C.2","State","State how many words the HL essay may be.",["1,200–1,500","800–1,000","1,500–2,000","4,000"],0,"The HL essay is 1,200–1,500 words on one work or text studied, developing a line of inquiry. 4,000 words is the extended essay.");
